def f32(value):return struct.unpack('<f',struct.pack('<f',value))[0]
def word(value):return f'{struct.unpack("<I",struct.pack("<f",value))[0]:08x}'
def numeric_string(row,count):
 require(row['storage']=='string','Legacy color source is not a string');raw=row['raw'];tokens=raw.split();require(len(tokens)==count,'Legacy color string arity differs')
 values=[float(value)for value in tokens];require(all(math.isfinite(value)for value in values),'Nonfinite color source');rounded=[f32(value)for value in values]
 # Independent host C sscanf checks these finite source literals; no target code runs.
 scan=ctypes.CDLL(None).sscanf;scan.restype=ctypes.c_int;scan.argtypes=[ctypes.c_char_p,ctypes.c_char_p];buffer=(ctypes.c_float*count)();result=scan(raw.encode('ascii'),(' '.join(['%f']*count)).encode(),*[ctypes.byref(buffer,i*4)for i in range(count)])
 require(result==count and [word(value)for value in buffer]==[word(value)for value in rounded],'Host sscanf source words differ')
 return {'raw':raw,'values':rounded,'words':[word(value)for value in rounded]}

def source_rows(pin,compiled,raw):
 require(len(raw)==2720 and witness.sha(raw)==SOURCE_SHA256,'Restored Troy source bytes differ');witness.pinned(TROY_READER,TROY_READER_SHA256);parsed=legacy_troy.read(raw);record=pin['records'][SOURCE_NAME]
 require(parsed==record['typed']and legacy_troy.decode(parsed,record['labels'])==record['decoded'],'Original typed or decoded Troy record differs');require(len(parsed['rows'])==272,'Original Troy row count differs');modulation.source_rows(pin,compiled)
 typed={row['hash']:row for row in parsed['rows']};rows=[]
 for index,profile in enumerate(compiled['profiles']):
  require(profile['sourceRecord']==SOURCE_NAME,'Gromp color source record differs');section=profile['sourceSection'];require(record['decoded']['values']['System']['GroupPart'+str(profile['sourceIndex']+1)]==section,'Gromp section/index linkage differs')
  base_key=modulation.source_key(section,'p-xrgba');base_row=typed.get(base_key);base=numeric_string(base_row,4)if base_row else {'raw':None,'values':[1.,1.,1.,1.],'words':['3f800000']*4};keys=[]
  for ordinal,key in enumerate(profile['colorCurve'],1):
   field='p-xrgba'+str(ordinal);hash_key=modulation.source_key(section,field);require(hash_key in typed,'Gromp color key missing');value=numeric_string(typed[hash_key],5)
   require(legacy_troy.semantic(typed[hash_key]['raw'])==[key['time'],*key['value']],'Compiled Gromp color key differs')
   prepared=[f32(value['values'][lane+1]*base['values'][lane])for lane in range(4)];keys.append({'field':field,'sdbm':hash_key,'source':value,'timeWord':value['words'][0],'preparedRgba':prepared,'preparedWords':[word(v)for v in prepared]})
  next_key=modulation.source_key(section,'p-xrgba'+str(len(keys)+1));require(next_key not in typed,'Gromp color key scope expands');require(all(keys[i-1]['source']['values'][0]<keys[i]['source']['values'][0]for i in range(1,len(keys))),'Gromp color times are not ordered')
  expected_base=legacy_troy.semantic(base['raw'])if base['raw']else [1,1,1,1];require(profile['color']==expected_base,'Compiled Gromp base color differs')
  fields=['e-rgba','e-rgba1',*[f'p-xrgba{channel}P{suffix}'for channel in 'RGBA'for suffix in ['',1]]];omissions=[]
  for field in fields:
   hash_key=modulation.source_key(section,field);require(hash_key not in typed,'Birth/probability color field is present');omissions.append({'field':field,'sdbm':hash_key})
  rows.append({'profileIndex':index,'section':section,'kind':profile['kind'],'base':base,'keys':keys,'firstMissingNumberedKey':next_key,'absentBirthAndProbabilityKeys':omissions})
 require(len(rows)==8 and sum(len(row['keys'])for row in rows)==27,'Gromp color scope differs');return {'resource':{'path':str(SOURCE_PATH),'bytes':len(raw),'sha256':SOURCE_SHA256},'typedRows':272,'originalTypedAndDecodedRecordsExact':True,'profiles':rows,'hostScanfSourceWordsExact':True}

def verify(image,core):
 witness.pinned(modulation.OUTPUT,MODULATION_SHA256);modulation.verify(image,core);starts=function_starts(image.data,core['functionStarts']);spans=[]
 for name,start,end,digest in SPANS:
  slot=bisect.bisect_left(starts,start);require(starts[slot:slot+2]==[start,end],'Color-curve function bounds differ: '+name);raw=image.at(start,end-start);require(witness.sha(raw)==digest,'Color-curve function bytes differ: '+name);spans.append({'name':name,'start':hex(start),'next':hex(end),'bytes':len(raw),'sha256':digest,'hex':raw.hex()})
 selected=[]
 for pc,expected,reading in WORDS:
  require(image.word(pc)==expected,'Color-curve selected word differs: '+reading);selected.append({'address':hex(pc),'word':f'{expected:08x}','reading':reading})
 literals=[]
 for address,value in [(0x102278a30,'p-xrgba'),(0x102277f6c,'e-rgba')]:
  require(image.at(address,len(value)+1)==value.encode()+b'\0','Color-curve literal differs');literals.append({'address':hex(address),'value':value})
